  "脚、足部": ["腳、足部", "Foot", "足・足の部分"],
  "脚步利落、毫不犹豫地快走": ["腳步利落、毫不猶豫地快走", "Walk quickly and decisively without hesitation", "ためらわず、足取りも軽く速く歩く様子"],
  "脚疼": ["腳疼", "Foot pain", "足が痛い"],
  "脚（あし）": ["脚（あし）", "脚（あし）", "脚（あし）"],
